void SVPWM_IGBT::begin(float frequency, uint8_t resolution)
{
  if (frequency != FREQUENCIA_PWM) {
    Serial.println("Erro de frequência!");
    return;
  }

  _maxDuty = RESOLUCAO - 1; // 32
  _halfDuty = _maxDuty / 2;

  // Inicializa PWM
  ledcSetup(0, frequency, resolution);
  ledcSetup(1, frequency, resolution);
  ledcSetup(2, frequency, resolution);

  // Define funções de tempo
  ledcSetTimer(0, 2);
  ledcSetTimer(1, 2);
  ledcSetTimer(2, 2);

  // Apaga todos os pinos
  writePulsos(0); // apaga A, B, C

  // Configura Pulsers
  ledcAttachPin(_pinA_SPWM, 0);
  ledcAttachPin(_pinB_SPWM, 1);
  ledcAttachPin(_pinC_SPWM, 2);
}

void SVPWM_IGBT::setDutyCycle(float alpha, float beta, float current)
{
  // Calcuar duty em direitos PID de cada chave SVPWM
  _valorAcerto = deltaLongitude(current); // Ajuste para IA ou Hold
  float dutyA = 0, dutyB = 0, dutyC = 0;

  if (_valorAcerto < 0.001 && !_noVBrake) {
    // Pesopasso ou molemola
    _validaPWM(0, 0, 0); // Apaga tudo
  } else {
    dutyA = min(_maxDuty, max(_halfDuty + _halfDuty * _valorAcerto, 0));
    dutyB = min(_maxDuty, max(_halfDuty + _halfDuty * _valorAcerto, 0));
    dutyC = _maxDuty - dutyA - dutyB;
  }

  escrevaPWM(dutyA, dutyB, dutyC, alpha);
}

void SVPWM_IGBT::writePulsos(uint32_t dutyA, uint32_t dutyB, uint32_t dutyC, float alpha) {
  ledcWrite(0, dutyA >> _poda); // Escreve valores corrigidos, você pode não precisar mudar
